import re,os
imports={}
for dp,dn,fn in os.walk('AlgebraicJacobian'):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f); m=p[:-5].replace('/','.')
            imports[m]=[mo.group(1) for line in open(p) for mo in [re.match(r'import\s+(AlgebraicJacobian[\w.]*)',line)] if mo]
have=set('AlgebraicJacobian.'+f.replace('/','.') for f in open('/tmp/cone.txt').read().split())
seen=set(); order=[]
def visit(m):
    if m in seen: return
    seen.add(m)
    for i in imports.get(m,[]): visit(i)
    order.append(m)
visit('AlgebraicJacobian.RiemannRoch.ChiCurve')
new=[m for m in order if m not in have]
tot=0
for m in new:
    n=sum(1 for _ in open(m.replace('.','/')+'.lean')); tot+=n
    print(f"{n:5d}  {m}")
print("NEW:",len(new),"files",tot,"lines")
EOF
